export type StopReason =
  | "stop"
  | "length"
  | "content_filter"
  | "refusal"
  | "tool_calls"
  | "pause_turn"
  | "canceled"
  | "error"
  | "unknown"
;

export type CompactStatus =
  | "started"
  | "queued"
;

/** The reason a compaction runs: the context grew past its limit, or the user asked. */
